/* @autogenerated */
import { computed, inject, Injectable, InjectionToken, signal, Signal, untracked } from '@angular/core';
import { ActivatedRouteSnapshot, GuardsCheckEnd, Router } from '@angular/router';
import { filter } from 'rxjs';
import { AppStateService } from '@shared/context/state/app-state.service';
import { WORKSPACE_LIST } from '../workspaces.config';
import { NavItem, UserMenuItem, WorkspaceDefinition } from './workspace.model';

/** Workspaces de la aplicación; el primero con `path` vacío es el de por defecto. */
export const WORKSPACES = new InjectionToken<WorkspaceDefinition[]>('WORKSPACES', {
  providedIn: 'root',
  factory: () => WORKSPACE_LIST,
});

/** Clave de `data` con la que una ruta indica su workspace. */
export const WORKSPACE_DATA = 'workspace';

/**
 * Workspace activo: el de la ruta a la que se navega. Se fija al pasar los guards de una navegación real,
 * antes de pintar la página, y con él cambian el menú, los selectores y el ámbito del contexto.
 * (No es un guard: el menú evalúa los guards de cada entrada para saber si mostrarla.)
 */
@Injectable({ providedIn: 'root' })
export class WorkspaceStateService {
  readonly workspaces = inject(WORKSPACES);
  private readonly appState = inject(AppStateService);
  private readonly router = inject(Router);
  private readonly activeName = signal(this.fallback().name);

  readonly active: Signal<WorkspaceDefinition> = computed(() => this.find(this.activeName()) ?? this.fallback());
  readonly nav = computed<NavItem[]>(() => this.active().nav);
  readonly userMenu = computed<UserMenuItem[]>(() => this.active().userMenu);
  readonly selectors = computed(() => this.active().selectors);

  constructor() {
    this.activate(this.activeName());
    this.router.events
      .pipe(filter((event): event is GuardsCheckEnd => event instanceof GuardsCheckEnd && !!event.shouldActivate))
      .subscribe((event) => this.activate(workspaceOf(event.state.root) ?? this.fallback().name));
  }

  activate(name: string): void {
    const workspace = this.find(name) ?? this.fallback();
    this.activeName.set(workspace.name);
    this.appState.contextScope.set(workspace.name);
  }

  find(name: string | undefined): WorkspaceDefinition | undefined {
    return this.workspaces.find((workspace) => workspace.name === name);
  }

  /** Comandos del router para `route` dentro de `workspace` (por defecto, el activo). */
  link(route?: string, workspace?: string): string[] {
    const target = (workspace ? this.find(workspace) : untracked(this.active)) ?? this.fallback();
    return [
      '/',
      untracked(this.appState.language),
      untracked(this.appState.tenant),
      ...(target.path ? [target.path] : []),
      ...(route ? route.split('/') : []),
    ];
  }

  /** La URL de `link()` sin la barra inicial, como la espera `RouteAccessService`. */
  url(route?: string, workspace?: string): string {
    return this.link(route, workspace).slice(1).join('/');
  }

  private fallback(): WorkspaceDefinition {
    return this.workspaces.find((workspace) => !workspace.path) ?? this.workspaces[0];
  }
}

/** Workspace declarado en `data` por la ruta o por alguno de sus padres. */
function workspaceOf(root: ActivatedRouteSnapshot): string | undefined {
  let found: string | undefined;
  for (let node: ActivatedRouteSnapshot | null = root; node; node = node.firstChild) {
    found = node.routeConfig?.data?.[WORKSPACE_DATA] ?? found;
  }
  return found;
}
